  def_dsp: { en: 'Drip + sprinkler + pivot only (sum of NISR table cells, computed by the team)', fr: 'Goutte-à-goutte + aspersion + pivot seulement (somme des cellules NISR, calculée par l’équipe)', rw: 'Ibitonyanga + kuminjagira + pivot gusa (igiteranyo cy’imibare ya NISR, cyabazwe n’itsinda)' },
  def_farmers_modern: { en: 'NISR: irrigating farmers who used modern irrigation (farmer level)', fr: 'NISR : agriculteurs irrigants utilisant l’irrigation moderne (niveau agriculteur)', rw: 'NISR: abahinzi buhira bakoresheje kuhira bigezweho (ku muhinzi)' },
