  m_trend_stable: { en: 'In %s, the share went from %s (%s) to %s (%s). The 95%% intervals overlap, so the change may be sampling noise.', fr: 'À %s, la part est passée de %s (%s) à %s (%s). Les intervalles à 95 %% se chevauchent : l’écart peut venir de l’échantillon.', rw: 'Muri %s, igice cyavuye kuri %s (%s) kigera kuri %s (%s). Intera za 95%% zirahura: impinduka ishobora guturuka ku cyitegererezo.' },
  c_trend: { en: 'Trend by season, 2019–2026 (survey estimates and NISR published points)', fr: 'Évolution par saison, 2019–2026 (estimations d’enquête et points publiés NISR)', rw: 'Uko bihinduka ku gihembwe, 2019–2026 (igereranya n’imibare ya NISR)' },
  c_inputs: { en: 'Share of plots by farm practice, latest survey season', fr: 'Part des parcelles par pratique, dernière saison d’enquête', rw: 'Igice cy’imirima ku buryo bw’ubuhinzi, igihembwe giheruka' },
  c_province: { en: 'Share of plots irrigated by province, 2019–2022 vs 2023–2025', fr: 'Part des parcelles irriguées par province, 2019–2022 vs 2023–2025', rw: 'Igice cy’imirima yuhirwa ku ntara, 2019–2022 na 2023–2025' },
  c_production: { en: 'Production by crop group, thousand tonnes', fr: 'Production par groupe de cultures, milliers de tonnes', rw: 'Umusaruro ku itsinda ry’ibihingwa, toni ibihumbi' },
  c_season_c: { en: 'Share of plots irrigated in dry Season C', fr: 'Part des parcelles irriguées en saison sèche C', rw: 'Igice cy’imirima yuhirwa mu gihembwe C' },
  about_text: {
    en: 'An independent project by Team NiyoIshimwe for the NISR 2026 Big Data Hackathon, Track 1 (agricultural productivity, small-scale irrigation). It turns NISR survey data and rainfall records into a shortlist of districts for irrigation field assessment. It is not an official NISR product, and NISR does not endorse its suggestions.',
    fr: 'Projet indépendant de l’équipe NiyoIshimwe pour le NISR 2026 Big Data Hackathon, piste 1 (productivité agricole, petite irrigation). Il transforme les données d’enquête du NISR et les pluies en une liste de districts pour évaluation de terrain. Ce n’est pas un produit officiel du NISR et le NISR n’en approuve pas les suggestions.',
    rw: 'Umushinga wigenga w’itsinda NiyoIshimwe mu marushanwa NISR 2026 Big Data Hackathon, Track 1 (umusaruro w’ubuhinzi, kuhira bito). Uhindura amakuru y’ubushakashatsi bwa NISR n’imvura mo urutonde rw’uturere two gusura. Si igicuruzwa cyemewe cya NISR, kandi NISR ntiyemeza ibyo utanga.',
  },
  ai_text: { en: 'This project used AI assistance (Claude, by Anthropic). The hackathon requires disclosure:', fr: 'Ce projet a utilisé une assistance IA (Claude, d’Anthropic). Le hackathon exige de le déclarer :', rw: 'Uyu mushinga wakoresheje ubufasha bwa AI (Claude ya Anthropic). Amarushanwa asaba kubitangaza:' },
  ai_1: { en: 'Drafting code for data preparation, the website, the Shiny app and the models; the team reviews and runs it.', fr: 'Rédaction de code (préparation des données, site, application Shiny, modèles), relu et exécuté par l’équipe.', rw: 'Kwandika kode (gutegura amakuru, urubuga, porogaramu ya Shiny, ibyitegererezo); itsinda rirayisuzuma rikanayikoresha.' },
  ai_2: { en: 'Drafting documentation, page text, the data audit, and the French and Kinyarwanda translations (not yet reviewed by native speakers).', fr: 'Rédaction de la documentation, des textes, de l’audit des données et des traductions française et kinyarwanda (pas encore relues par des locuteurs natifs).', rw: 'Kwandika inyandiko, amagambo ku rubuga, isuzuma ry’amakuru n’ubusobanuro bw’Igifaransa n’Ikinyarwanda (butarasuzumwa n’abavuga izo ndimi kavukire).' },
  ai_3: { en: 'Every project estimate comes from code run on NISR data. NISR published figures were looked up with AI help and each one is linked to its source table so it can be checked.', fr: 'Chaque estimation du projet vient de code exécuté sur les données du NISR. Les chiffres publiés du NISR ont été recherchés avec l’aide de l’IA et chacun est lié à son tableau source pour vérification.', rw: 'Buri gereranya ry’umushinga rituruka kuri kode ikoreshwa ku makuru ya NISR. Imibare yatangajwe na NISR yashakishijwe hifashishijwe AI kandi buri umwe uhujwe n’imbonerahamwe yawo kugira ngo ugenzurwe.' },
  kpi_rule: { en: 'Every number card and chart states its measure and denominator, period, kind of number (project estimate, NISR published, model output or index) and source, next to it.', fr: 'Chaque carte et graphique indique à côté sa mesure et son dénominateur, la période, le type de chiffre (estimation du projet, publié NISR, modèle ou indice) et la source.', rw: 'Buri karita n’igishushanyo bigaragaza iruhande igipimwa n’icyo kigabanywa, igihe, ubwoko bw’umubare (igereranya ry’umushinga, byatangajwe na NISR, icyitegererezo cyangwa igipimo) n’inkomoko.' },
  downloads_text: { en: 'Aggregated tables only (no microdata). Every CSV repeats the measure, period, kind of number, source and link on each row, with n, PSU count and quality label where relevant.', fr: 'Tableaux agrégés seulement (pas de microdonnées). Chaque CSV répète sur chaque ligne la mesure, la période, le type de chiffre, la source et le lien, avec n, le nombre d’UPE et la qualité si pertinent.', rw: 'Imbonerahamwe zikusanyije gusa (nta makuru y’ibanze). Buri CSV isubiramo kuri buri murongo igipimwa, igihe, ubwoko bw’umubare, inkomoko n’ihuza, na n, umubare wa PSU n’ubuziranenge aho bikenewe.' },
  m_forest_controls: { en: 'Adjusted for: %s.', fr: 'Ajusté pour : %s.', rw: 'Byahujwe hakurikijwe: %s.' },
  m_ladder: { en: 'For %s, average yield is %s kg/ha on plots with none of these inputs and %s kg/ha on plots with %s of them. Descriptive only: these plots differ in other ways too.', fr: 'Pour %s, le rendement moyen est de %s kg/ha sans aucun de ces intrants et de %s kg/ha avec %s d’entre eux. Descriptif : ces parcelles diffèrent aussi autrement.', rw: 'Kuri %s, umusaruro ugereranyije ni %s kg/ha ku mirima idakoresha izi nyongeramusaruro na %s kg/ha ku mirima ikoresha %s muri zo. Ni ibisobanuro gusa: iyo mirima itandukanye no mu bindi.' },
